callGraph.callee:
getMyProfile().then((result) => {
      if (cancelled) return;
      setProfile(result);
      if (!result.username) router.replace('/dashboard');
    }).catch

getTradeCharacters(selectedSystemId).then((result) => {
      if (!current) return;
      setCharacters(result.characters);
      const own = result.characters.filter((character) => character.is_mine);
      const others = result.characters.filter((character) => !character.is_mine);
      setSenderCharacterId(own[0]?.id ?? '');
      setRecipientCharacterId(others[0]?.id ?? '');
      setSenderSelection({});
      setRecipientSelection({});
    }).catch((error) => {
      if (current) {
        setCharacters([]);
        setMessage(error instanceof Error ? error.message : 'Não foi possível carregar os personagens.');
        setMessageIsError(true);
      }
    }).finally

getTradeCharacters(selectedSystemId).then((result) => {
      if (!current) return;
      setCharacters(result.characters);
      const own = result.characters.filter((character) => character.is_mine);
      const others = result.characters.filter((character) => !character.is_mine);
      setSenderCharacterId(own[0]?.id ?? '');
      setRecipientCharacterId(others[0]?.id ?? '');
      setSenderSelection({});
      setRecipientSelection({});
    }).catch

getTradeCharacterInventory(selectedSystemId, senderCharacterId).then((result) => {
      if (current) setSenderStacks(result.stacks);
    }).catch((error) => {
      if (current) {
        setSenderStacks([]);
        setMessage(error instanceof Error ? error.message : 'Não foi possível carregar seu inventário.');
        setMessageIsError(true);
      }
    }).finally

getTradeCharacterInventory(selectedSystemId, recipientCharacterId).then((result) => {
      if (current) setRecipientStacks(result.stacks);
    }).catch((error) => {
      if (current) {
        setRecipientStacks([]);
        setMessage(error instanceof Error ? error.message : 'Não foi possível carregar o inventário do outro personagem.');
        setMessageIsError(true);
      }
    }).finally

getMyDailyLoginSystems().then((value) => {
      if (active) setSystems(value);
    }).catch((cause) => {
      if (active) setError(cause instanceof Error ? cause.message : 'Não foi possível carregar seus sistemas para troca.');
    }).finally
